# Generates the reference fixture read by `faer/tests/polar.rs` (colmat-rs#60).
# Run once, offline, and check the output in:
#
#     julia --startup-file=no --project=<env> faer/tests/fixtures/polar_reference/generate.jl
#
# where <env> has MatrixFactorizations.jl at the reference commit of the issue:
#
#     Pkg.add(url="https://github.com/JuliaLinearAlgebra/MatrixFactorizations.jl",
#             rev="a38f07fbbcb8abebb203bf67fc745b8c262d6d19")
#
# MatrixFactorizations.jl is MIT, Copyright (c) 2019 JuliaLinearAlgebra; its `polar.jl` is based
# on the PolarFact package by Weijian Zhang (MIT). Only its output is used here, as the test
# oracle.
#
# For each case the fixture holds A (17 significant digits, exact round trip) and the polar
# factors from `polar(A; alg = :svd)`; a full-rank polar decomposition is unique, so the test
# compares entry by entry. The script also checks that `alg = :qdwh` agrees.
#
# - `left`, m >= n: A = W P, W is m x n with orthonormal columns, P is n x n.
# - `right`, m <= n: A = P Wh, Wh is m x n with orthonormal rows, P is m x m. MatrixFactorizations.jl
#   only takes m >= n, so this is `polar(A')` read as A = H U'.
#
# The 6 x 4 cases have singular values from 1 down to 1e-8 (condition 1e8). A complex matrix is
# written as its real and imaginary parts.
using MatrixFactorizations, LinearAlgebra, Printf, Random

const OUT = joinpath(@__DIR__, "polar.txt")

fmt(x::Float64) = @sprintf("%.17g", x)
function writemat(io, name, M)
    parts = eltype(M) <: Complex ? [("_re", real.(M)), ("_im", imag.(M))] : [("", M)]
    for (suffix, P) in parts
        println(io, name, suffix, " ", size(P, 1), " ", size(P, 2))
        for i in 1:size(P, 1)
            println(io, join(fmt.(P[i, :]), " "))
        end
    end
end

# W and P of A = W P, m >= n, checked against the QDWH method of the same package
function left_polar_reference(A)
    W, P = polar(A; alg = :svd)
    Wq, Pq = polar(A; alg = :qdwh)
    tol = 1e-12 * cond(A)
    @assert norm(W * P - A) <= 1e-13 * norm(A)
    @assert norm(W' * W - I) <= 1e-13
    @assert norm(W - Wq) <= tol && norm(P - Pq) <= tol * norm(A)
    W, P
end

function ill_conditioned(rng, T, m, n)
    U = Matrix(qr(randn(rng, T, m, m)).Q)[:, 1:n]
    V = Matrix(qr(randn(rng, T, n, n)).Q)
    U * Diagonal(exp10.(range(0, -8; length = n))) * V'
end

open(OUT, "w") do io
    println(io, "# generated by faer/tests/fixtures/polar_reference/generate.jl")
    println(io, "# julia ", VERSION, ", MatrixFactorizations.jl ",
        pkgversion(MatrixFactorizations), " at a38f07fbbcb8abebb203bf67fc745b8c262d6d19")
    rng = MersenneTwister(60)
    for T in (Float64, ComplexF64)
        dtype = T == Float64 ? "f64" : "c64"
        for (kind, A) in (("left", randn(rng, T, 5, 3)), ("left", randn(rng, T, 4, 4)),
                          ("right", randn(rng, T, 3, 5)), ("left", ill_conditioned(rng, T, 6, 4)))
            m, n = size(A)
            println(io, "case ", kind, " ", dtype, " ", m, " ", n)
            writemat(io, "a", A)
            if kind == "left"
                W, P = left_polar_reference(A)
                writemat(io, "w", W)
            else
                U, P = left_polar_reference(copy(A'))
                writemat(io, "w", copy(U'))
            end
            writemat(io, "p", P)
        end
    end
end
